Agregación: diaria → mensual
max_na &lt;- 3     # un mes es válido con 3 días sin dato como máximo

q_mensual &lt;- q_full |&gt;
  group_by(anio = year(fecha), mes = month(fecha)) |&gt;
  summarise(n_na = sum(is.na(q)),
            q    = mean(q, na.rm = TRUE),     # caudal: PROMEDIO
            .groups = "drop") |&gt;
  mutate(q = if_else(n_na &gt; max_na, NA, q))
. . .
pp_mensual &lt;- pp_full |&gt;
  group_by(anio = year(fecha), mes = month(fecha)) |&gt;
  summarise(n_na = sum(is.na(pp)),
            pp   = sum(pp, na.rm = TRUE),     # precipitación: SUMA
            .groups = "drop") |&gt;
  mutate(pp = if_else(n_na &gt; max_na, NA, pp))

Funciones propias

Escribir la limpieza UNA vez y reutilizarla
leer_senamhi &lt;- function(archivo) {
  read_excel(archivo, skip = 13) |&gt;
    rename(fecha = 1, hora = 2, valor = 3) |&gt;
    mutate(fecha = dmy(fecha)) |&gt;
    arrange(fecha, hora) |&gt;
    distinct(fecha, .keep_all = TRUE) |&gt;        # regla 00:00 → 05:00
    select(fecha, valor) |&gt;
    complete(fecha = seq(min(fecha), max(fecha), by = "day"))
}
. . .
q  &lt;- leer_senamhi("data/raw/caudal/Q_210201_PteCarretera_Huancane.xlsx")
pp &lt;- leer_senamhi("data/raw/precipitacion/PP_000786_Huancane.xlsx")
nrow(q)     #&gt; 25692

Todo el procesamiento de la sección 03 quedó en una línea. Si mañana cambia el formato de SENAMHI, se corrige en un solo lugar.

Funciones: argumentos por defecto
agregar_mensual &lt;- function(datos, fun = sum, max_na = 3) {
  datos |&gt;
    group_by(anio = year(fecha), mes = month(fecha)) |&gt;
    summarise(n_na  = sum(is.na(valor)),
              valor = fun(valor, na.rm = TRUE),
              .groups = "drop") |&gt;
    mutate(valor = if_else(n_na &gt; max_na, NA, valor))
}
. . .
pp_mensual &lt;- agregar_mensual(pp)                         # suma (por defecto)
q_mensual  &lt;- agregar_mensual(q, fun = mean)              # promedio
q_estricto &lt;- agregar_mensual(q, fun = mean, max_na = 0)  # sin vacíos

En el script también está agregar_anual(), que conserva solo los años con 12 meses válidos: 62 años de caudal.

Condicionales: if / else
umbrales &lt;- quantile(q_anual$valor, c(0.2, 0.8))
#&gt;   20%   80%
#&gt; 11.48 24.41

clasificar &lt;- function(q, p20, p80) {
  if (q &lt; p20) {
    "seco"
  } else if (q &gt; p80) {
    "húmedo"
  } else {
    "normal"
  }
}

clasificar(4.75, umbrales[1], umbrales[2])   # caudal medio de 2023
#&gt; "seco"

Todas las estaciones en un gráfico


pp_anual &lt;- pp_lista |&gt;
  map(\(d) d |&gt;
        agregar_mensual() |&gt;
        agregar_anual()) |&gt;
  list_rbind(names_to = "estacion")

ggplot(pp_anual,
       aes(anio, valor)) +
  geom_col(fill = "#0B5394") +
  facet_wrap(~ estacion,
             ncol = 1)

facet_wrap() hace un panel por estación. Entre 2010 y 2016 solo Cojata tiene años completos: es un vacío de toda la red, no de una estación.

ETP por Hargreaves-Samani
\[ETP = 0.0023 \cdot R_a \cdot (T_{media} + 17.8) \cdot \sqrt{T_{max} - T_{min}}\]
hargreaves &lt;- function(tmax, tmin, lat, fecha) {
  tmedia &lt;- (tmax + tmin) / 2
  0.0023 * radiacion_ext(lat, fecha) * (tmedia + 17.8) *
    sqrt(pmax(tmax - tmin, 0))
}
. . .
etp_dia &lt;- temp |&gt;
  left_join(info_sub, by = "subcuenca") |&gt;        # latitud y área
  mutate(etp = hargreaves(tmax, tmin, lat, fecha))

etp_cuenca_mes &lt;- etp_dia |&gt;
  group_by(subcuenca, area_km2, fecha = floor_date(fecha, "month")) |&gt;
  summarise(etp = sum(etp), .groups = "drop") |&gt;   # diaria -&gt; mensual
  group_by(fecha) |&gt;
  summarise(etp = weighted.mean(etp, area_km2))    # ponderado por área
#&gt; ETP media anual 1981–2020: 1105 mm

\(R_a\) = radiación extraterrestre (FAO-56), función de la latitud del centroide y del día del año.
